import { _decorator, CCBoolean, CCInteger, Component, instantiate, Layout, Node, Prefab, Size, UITransform, v3, Vec3 } from 'cc';
import { rollDirection } from '../../Model/ReelDataBase';
const { ccclass, property } = _decorator;

@ccclass('Test')
export class Test extends Component {
    @property(CCBoolean)
    private havePrepareIcon: boolean = false;

    @property(CCBoolean)
    private useLayout: boolean = false;

    @property(CCBoolean)
    private haveShowIcon: boolean = false;

    @property(CCInteger)
    private iconInReelAmount = 0;

    @property(Node)
    private rootNode: Node = null;

    @property(Node)
    private iconList: Node[] = [];

    @property({ type: rollDirection })
    private reelDir: rollDirection = rollDirection.Down;

    @property(Prefab)
    private iconPrefab: Prefab = null;

    private iconAmount: number = 0;
    private _isVertical: boolean = false;
    private unitDis: number = 0;
    private _iconPos: Vec3[] = [];

    @property(CCInteger)
    private iconSpacing: number = 0;
    private iconStartPos: number = 0;
    private upOrRightUnit: number = 0;

    private _endBouncePos: Vec3 = Vec3.ZERO;
    private _startPullPos: Vec3 = Vec3.ZERO;

    private originalPos: Vec3 = Vec3.ZERO;
    private targetPos: Vec3 = Vec3.ZERO;

    protected start(): void {
        this.createIcon();
        this.init(this.iconList);
    }

    public init(iconNodes: Node[]): void {
        this.iconAmount = this.havePrepareIcon ? iconNodes.length / 2 : iconNodes.length;

        let rollDirUnit: number[][] = [[0, -1], [0, 1], [-1, 0], [1, 0]];
        let currentDirUnit = rollDirUnit[this.reelDir];
        this._isVertical = this.reelDir === rollDirection.Up || this.reelDir === rollDirection.Down;

        let iconSize = iconNodes[0].getComponent(UITransform).contentSize;
        this.unitDis = this._isVertical ? iconSize.y + this.iconSpacing : iconSize.x + this.iconSpacing;
        let rollDis = this.unitDis * this.iconAmount;
        let startPos: number = (this.iconAmount / 2 - 1) * this.unitDis + (this.unitDis / 2);
        startPos += this.havePrepareIcon ? rollDis : 0;
        this.iconStartPos = this._isVertical ? -currentDirUnit[1] * startPos : -currentDirUnit[0] * startPos;
        this.upOrRightUnit = this.reelDir === rollDirection.Up || this.reelDir === rollDirection.Right ? -1 : 1;

        if (this.useLayout) {
            this.calculateLayOutIconPos(iconNodes.length);
        }
        else {
            this.calculateInitIconPos(iconNodes.length);
            this.initIconPos(iconNodes);
        }

        this.originalPos = this.rootNode.getPosition();
        this.targetPos = this._isVertical ? v3(0, rollDis * currentDirUnit[1], 0) : v3(rollDis * currentDirUnit[0], 0, 0);
    }

    protected createIcon(): void {
        for (let index = 0; index < this.iconInReelAmount; index++) {
            let icon = instantiate(this.iconPrefab);
            icon.setParent(this.rootNode);
            this.iconList.push(icon);
        }
    }

    protected calculateLayOutIconPos(iconInReelAmount: number): void {
        let layout: Layout = this.rootNode.addComponent(Layout);
        if (this.haveShowIcon) {
            iconInReelAmount -= 2;
        }
        if (this._isVertical) {
            layout.type = Layout.Type.VERTICAL;
            layout.verticalDirection = this.reelDir === rollDirection.Up ? Layout.VerticalDirection.BOTTOM_TO_TOP : Layout.VerticalDirection.TOP_TO_BOTTOM;
            layout.spacingY = this.iconSpacing;

            if (this.havePrepareIcon) {
                let paddingTop = this.unitDis * (iconInReelAmount / 2) * -this.upOrRightUnit;
                layout.paddingTop = paddingTop;
            }
        }
        else {
            layout.type = Layout.Type.HORIZONTAL;
            layout.horizontalDirection = this.reelDir === rollDirection.Right ? Layout.HorizontalDirection.LEFT_TO_RIGHT : Layout.HorizontalDirection.RIGHT_TO_LEFT;
            layout.spacingX = this.iconSpacing;

            if (this.havePrepareIcon) {
                let paddingLeft = this.unitDis * (iconInReelAmount / 2) * this.upOrRightUnit;
                layout.paddingLeft = paddingLeft;
            }
        }

        layout.resizeMode = Layout.ResizeMode.CONTAINER;
        layout.updateLayout();
    }

    protected calculateInitIconPos(iconInReelAmount: number): void {
        for (let index = 0; index < iconInReelAmount; index++) {
            let newPos: Vec3 = this.calculateIconPos(index);
            this._iconPos.push(newPos);
        }

        this._endBouncePos = this.calculateIconPos(- 1);
        this._startPullPos = this.calculateIconPos(iconInReelAmount);
    }

    protected calculateIconPos(iconIndex: number): Vec3 {
        let offset: number = this.unitDis * iconIndex;
        let finalPos: number = (this.iconStartPos * this.upOrRightUnit - offset) * this.upOrRightUnit;
        let newPos: Vec3 = this._isVertical ? v3(0, finalPos, 0) : v3(finalPos, 0, 0);

        return newPos;
    }

    protected initIconPos(iconNodes: Node[]): void {
        for (let index = 0; index < iconNodes.length; index++) {
            iconNodes[index].setPosition(this._iconPos[index]);
        }
    }
}


